// ═══════════════════════════════════════════════════════════════════════
// EYWA v3.32 Multi-workspace fan-out + property mapping per workspace
// ═══════════════════════════════════════════════════════════════════════
// Per Bible §18.7.5a Dynamic Token Pattern. One input row → N output items
// (one per target workspace). Each item carries its own (token, ds_id, payload).
//
// Env vars (set in n8n Settings → Environments):
//   NOTION_TOKEN_VT_INTELLIGENCE         = 'ntn_xxxxxxxxxxxxxxxxxxxxxxxxxx'
//   NOTION_TOKEN_THE_GIFTED_SYNAPSE      = 'ntn_yyyyyyyyyyyyyyyyyyyyyyyyyy'
//   NOTION_DB_ENTITY_GRAPH_VT_INTELLIGENCE     = '434d8053-62be-4ff1-8d42-f503f2e07741'  (data_source_id)
//   NOTION_DB_ENTITY_GRAPH_THE_GIFTED_SYNAPSE  = '37bbe9c6-bf3c-8103-9945-000b1186b63e'  (data_source_id)
//   ALLOWED_BRANDS_VT_INTELLIGENCE       = 'vth-biodent,bio-dental-wellness,...'
//   ALLOWED_BRANDS_THE_GIFTED_SYNAPSE    = 'classy-clinic,deezy-dental,...'
//   WORKSPACE_ROLE_VT_INTELLIGENCE       = 'operator' | 'editorial' | 'curator'
//   WORKSPACE_ROLE_THE_GIFTED_SYNAPSE    = 'operator' | 'editorial' | 'curator'
// ═══════════════════════════════════════════════════════════════════════

const WORKSPACES = {
  vt_intelligence: {
    token: $env.NOTION_TOKEN_VT_INTELLIGENCE,
    entity_graph_ds_id: $env.NOTION_DB_ENTITY_GRAPH_VT_INTELLIGENCE,
    allowed_brands: ($env.ALLOWED_BRANDS_VT_INTELLIGENCE || '')
      .split(',').map(s => s.trim()).filter(Boolean),
    role: $env.WORKSPACE_ROLE_VT_INTELLIGENCE || 'operator',
    // Production workspace — Brand Scope is type=relation (Phase 2 backfill handles)
    brand_scope_type: 'relation',
  },
  the_gifted_synapse: {
    token: $env.NOTION_TOKEN_THE_GIFTED_SYNAPSE,
    entity_graph_ds_id: $env.NOTION_DB_ENTITY_GRAPH_THE_GIFTED_SYNAPSE,
    allowed_brands: ($env.ALLOWED_BRANDS_THE_GIFTED_SYNAPSE || '')
      .split(',').map(s => s.trim()).filter(Boolean),
    role: $env.WORKSPACE_ROLE_THE_GIFTED_SYNAPSE || 'operator',
    // Canonical-clean workspace — Brand Scope is type=multi_select (text-based, no Phase 2)
    brand_scope_type: 'multi_select',
  },
};

// Capitalize first letter (used for Entity Type & Schema.org Type select values)
const toTitle = s => (s ? s.charAt(0).toUpperCase() + s.slice(1) : '');

function buildProperties(row, ws) {
  const config = WORKSPACES[ws];
  const props = {
    'Entity Name': { title: [{ text: { content: row.entity_name || '(untitled)' } }] },
    'Entity Slug': { rich_text: [{ text: { content: row.entity_slug || '' } }] },
    'Fingerprint': { rich_text: [{ text: { content: row.fingerprint || '' } }] },
    'Fingerprint Display Name': { rich_text: [{ text: { content: row.fingerprint_display_name || '' } }] },
  };

  if (row.entity_type) {
    const types = Array.isArray(row.entity_type) ? row.entity_type : [row.entity_type];
    props['Entity Type'] = {
      multi_select: types.filter(Boolean).map(t => ({ name: toTitle(t) })),
    };
  }
  if (row.entity_subtype) {
    props['Entity Subtype'] = { select: { name: row.entity_subtype } };
  }
  if (row.schema_org_type) {
    props['Schema.org Type'] = { select: { name: row.schema_org_type } };
  }
  if (row.topic_cluster_id) {
    props['Topic Cluster ID'] = { rich_text: [{ text: { content: row.topic_cluster_id } }] };
  }
  if (row.topic_cluster_name) {
    props['Topic Cluster Name'] = { rich_text: [{ text: { content: row.topic_cluster_name } }] };
  }
  if (row.entity_lifecycle) {
    props['Entity Lifecycle'] = { select: { name: row.entity_lifecycle } };
  }
  if (row.programmatic_eligible !== null && row.programmatic_eligible !== undefined) {
    props['Programmatic Eligible'] = { checkbox: !!row.programmatic_eligible };
  }
  if (row.content_gap_flag !== null && row.content_gap_flag !== undefined) {
    props['Content Gap Flag'] = { checkbox: !!row.content_gap_flag };
  }
  if (row.wikidata_id) {
    props['Wikidata ID'] = { rich_text: [{ text: { content: row.wikidata_id } }] };
  }
  if (row.icd_10_code) {
    props['ICD-10 Code'] = { rich_text: [{ text: { content: row.icd_10_code } }] };
  }
  if (Array.isArray(row.center_scope) && row.center_scope.length) {
    props['Center Scope'] = { multi_select: row.center_scope.map(c => ({ name: c })) };
  }
  if (row.search_volume_total !== null && row.search_volume_total !== undefined) {
    props['Search Volume Total'] = { number: Number(row.search_volume_total) || 0 };
  }
  if (row.entity_authority_score !== null && row.entity_authority_score !== undefined) {
    props['Entity Authority Score'] = { number: Number(row.entity_authority_score) || 0 };
  }
  if (row.aliases) {
    props['Aliases'] = { rich_text: [{ text: { content: row.aliases } }] };
  }
  if (row.ai_entity_summary) {
    props['AI Entity Summary'] = { rich_text: [{ text: { content: row.ai_entity_summary } }] };
  }
  if (row.competing_entities) {
    props['Competing Entities'] = { rich_text: [{ text: { content: row.competing_entities } }] };
  }
  if (row.hreflang_group) {
    props['Hreflang Group'] = { rich_text: [{ text: { content: row.hreflang_group } }] };
  }

  // ─── Workspace-conditional: Brand Scope ──────────────────────────────
  // Production (vt): Brand Scope is type=relation — defer to Phase 2 backfill
  //                  (Phase 2 looks up Brand page_id per brand_slug)
  // Canonical (the_gifted): Brand Scope is type=multi_select — write as text now
  if (config.brand_scope_type === 'multi_select' && Array.isArray(row.brand_scope) && row.brand_scope.length) {
    props['Brand Scope'] = {
      multi_select: row.brand_scope.filter(s => s !== '*').map(s => ({ name: s })),
    };
  }
  // For 'relation' workspace, omit Brand Scope here — Phase 2 backfill workflow handles it

  // Always set Supabase Synced At — both workspaces have this prop (post-drift-fix)
  props['Supabase Synced At'] = { date: { start: new Date().toISOString() } };

  return props;
}

function decideTargetWorkspaces(row) {
  const targets = new Set();
  const brandScope = Array.isArray(row.brand_scope) ? row.brand_scope : [];
  const isUniversal = brandScope.includes('*');

  if (isUniversal) {
    // Universal entity → fan out to every operator-role workspace
    for (const [ws, cfg] of Object.entries(WORKSPACES)) {
      if (cfg.role === 'operator' || cfg.role === 'curator') {
        targets.add(ws);
      }
    }
    return Array.from(targets);
  }

  // brand_routing_map: { brand_slug: notion_workspace } — built by SELECT query
  const routingMap = row.brand_routing_map || {};
  for (const [slug, ws] of Object.entries(routingMap)) {
    const cfg = WORKSPACES[ws];
    if (!cfg) continue;
    if (!cfg.allowed_brands.includes(slug)) continue;
    targets.add(ws);
  }
  return Array.from(targets);
}

const out = [];
const errors = [];

for (const item of $input.all()) {
  const row = item.json;
  const targets = decideTargetWorkspaces(row);

  if (targets.length === 0) {
    errors.push({
      fingerprint: row.fingerprint,
      entity_name: row.entity_name,
      brand_scope: row.brand_scope,
      routing_map: row.brand_routing_map,
      reason: 'no_target_workspace: no brand in brand_scope has notion_workspace mapping OR not in any workspace allowed_brands list',
    });
    continue;
  }

  for (const ws of targets) {
    const config = WORKSPACES[ws];

    if (!config.token) {
      errors.push({
        fingerprint: row.fingerprint,
        workspace: ws,
        reason: `NOTION_TOKEN_${ws.toUpperCase()} env var not set`,
      });
      continue;
    }
    if (!config.entity_graph_ds_id) {
      errors.push({
        fingerprint: row.fingerprint,
        workspace: ws,
        reason: `NOTION_DB_ENTITY_GRAPH_${ws.toUpperCase()} env var not set`,
      });
      continue;
    }

    const dsId = config.entity_graph_ds_id.replace('collection://', '');
    const properties = buildProperties(row, ws);

    out.push({
      json: {
        // Metadata carried to downstream nodes
        _supabase_id: row.id,
        _fingerprint: row.fingerprint,
        _entity_name: row.entity_name,
        _workspace: ws,
        _brand_scope_type: config.brand_scope_type,
        // Authorization fields — used by HTTP Request node Bearer token expression
        notion_token: config.token,
        notion_ds_id: dsId,
        // Notion API 2025-09-03 payload — parent uses data_source_id (not database_id)
        payload: {
          parent: { type: 'data_source_id', data_source_id: dsId },
          properties,
        },
      },
    });
  }
}

if (errors.length) {
  console.log('[v3.32] Routing/validation errors:', JSON.stringify(errors, null, 2));
  // Errors are intentionally NOT emitted as workflow items — they're logged.
  // To send them to a 2nd Postgres LOG branch, restructure this node's outputs.
}
return out;

// ═══════════════════════════════════════════════════════════════════════
// Parse Notion API response — recover upstream metadata via paired items
// ═══════════════════════════════════════════════════════════════════════
// HTTP Request strips non-body fields, so _supabase_id/_fingerprint/_workspace
// must be pulled from the upstream Code node via $('NodeName').itemMatching(i).
// ═══════════════════════════════════════════════════════════════════════

const out = [];
const inputs = $input.all();
const UPSTREAM = 'Code: resolve workspaces + fan-out + build payload';

for (let i = 0; i < inputs.length; i++) {
  const item = inputs[i];
  const resp = item.json;
  const status = resp.statusCode;
  const body = resp.body;

  let upstream = {};
  try {
    const upItem = $(UPSTREAM).itemMatching(i);
    upstream = upItem ? upItem.json : {};
  } catch (e) {
    const arr = $items(UPSTREAM);
    upstream = arr[i] ? arr[i].json : {};
  }

  const supabaseId = upstream._supabase_id || null;
  const fingerprint = upstream._fingerprint || null;
  const workspace = upstream._workspace || null;
  const brandScopeType = upstream._brand_scope_type || null;

  if (status >= 200 && status < 300 && body && body.id) {
    out.push({
      json: {
        _supabase_id: supabaseId,
        _fingerprint: fingerprint,
        _workspace: workspace,
        _brand_scope_type: brandScopeType,
        notion_id: body.id,
        sync_state: brandScopeType === 'relation' ? 'notion_synced' : 'relations_backfilled',
        notion_synced_at: new Date().toISOString(),
        _needs_phase2_backfill: brandScopeType === 'relation',
        _ok: true,
      },
    });
  } else {
    out.push({
      json: {
        _supabase_id: supabaseId,
        _fingerprint: fingerprint,
        _workspace: workspace,
        _ok: false,
        _error: {
          status,
          notion_error_code: body && body.code || null,
          notion_error_message: body && body.message || 'unknown',
          notion_request_id: body && body.request_id || null,
        },
      },
    });
  }
}

return out;
